"""Load R reference cases from tests/reference/*.json (generated by validation/r/equate_*.R)."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

REFERENCE_DIR = Path(__file__).parent / "reference"


def load_reference(name: str) -> dict[str, Any]:
    """Return the parsed reference file ``tests/reference/<name>.json``."""
    with (REFERENCE_DIR / f"{name}.json").open(encoding="utf-8") as handle:
        data: dict[str, Any] = json.load(handle)
    return data


def cases_by_name(name: str) -> dict[str, dict[str, Any]]:
    """Return the cases of a reference file keyed by their ``name``."""
    return {case["name"]: case for case in load_reference(name)["cases"]}
